package agentusageview

import (
	"path/filepath"
	"strconv"

	"github.com/charmbracelet/lipgloss"

	sharedcomponents "github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/shortcut"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// baseFooterHeight is the blank line and the message line (Rule 124).
const baseFooterHeight = 2

// View is the table, whatever it holds (Rule 139).
func (m Model) View() string {
	if m.level == levelAgents {
		return m.agentTable.View()
	}
	return m.table.View()
}

// GetTitle names the view, and the project of the open session at the agents
// level (its short ID when the transcript named no project).
func (m Model) GetTitle() string {
	title := theme.IconAgentUsage + " Agent usage"
	if m.level != levelAgents {
		return title
	}
	leaf := shortID(m.open.ID)
	if m.open.Project != "" {
		leaf = filepath.Base(m.open.Project)
	}
	return title + " › " + leaf
}

// shortID is the start of a session ID, as the Session column shows it.
func shortID(id string) string {
	r := []rune(id)
	return string(r[:min(sessionIDPrefix, len(r))])
}

// GetIcon returns nothing: the title carries the icon.
func (m Model) GetIcon() string { return "" }

// GetHeaderInfo counts the sessions on screen, and the ones not listed when
// there are some.
func (m Model) GetHeaderInfo(_ string) []shortcut.HeaderInfo {
	if m.level == levelAgents {
		return m.agentsHeaderInfo()
	}
	info := []shortcut.HeaderInfo{
		{Key: "Sessions", Value: strconv.Itoa(len(m.table.Visible())), Style: theme.HeaderValueStyle},
	}
	if m.omitted > 0 {
		info = append(info, shortcut.HeaderInfo{Key: "Skipped", Value: strconv.Itoa(m.omitted), Style: theme.HeaderValueStyle})
	}
	return info
}

// agentsHeaderInfo counts the agents on screen and their tokens, both following
// the filter.
func (m Model) agentsHeaderInfo() []shortcut.HeaderInfo {
	rows := m.agentTable.Visible()
	var total int64
	for _, r := range rows {
		total += r.Tokens.Total()
	}
	return []shortcut.HeaderInfo{
		{Key: "Agents", Value: strconv.Itoa(len(rows)), Style: theme.HeaderValueStyle},
		{Key: "Tokens", Value: formatTokens(total), Style: theme.HeaderValueStyle},
	}
}

// GetShortcuts returns the same keys at both levels and in every state; what
// varies is Disabled, from the one availability the handlers also read
// (Rule 130).
func (m Model) GetShortcuts() shortcut.Shortcuts {
	a := m.availability()
	return shortcut.Shortcuts{
		{Key: "ctrl+r", Description: "Refresh"},
		{Key: "→", Description: "Open agents", Disabled: !a.Open.Enabled()},
		{Key: "esc", Description: "Go back", Disabled: !a.Close.Enabled()},
		{Key: "/", Description: "Filter"},
		{Key: "?", Description: "Help"},
	}
}

// GetFooterHeight budgets the footer (Rules 124, 136).
func (m Model) GetFooterHeight() int {
	h := baseFooterHeight + m.activeFilterBar().ExtraHeight()
	if m.level == levelAgents {
		h++ // the breadcrumb row
	}
	return h
}

// RenderFooter renders the breadcrumb at the agents level, the filter bar when
// visible, a blank line, and the message line.
func (m Model) RenderFooter(width int) string {
	line := theme.EmptyLineBg(width) + "\n" + m.footer.View(width, m.status())
	if bar := m.activeFilterBar(); bar.IsVisible() {
		line = bar.View() + "\n" + line
	}
	if m.level == levelAgents {
		line = m.breadcrumb(width) + "\n" + line
	}
	return line
}

// breadcrumb is Sessions › project › ID, the last one active and its parents
// dim, with the one cell of left padding Rule 123 asks for.
func (m Model) breadcrumb(width int) string {
	project := noProject
	if m.open.Project != "" {
		project = theme.ShortPath(m.open.Project, max(width/2, 1))
	}
	base := lipgloss.NewStyle().Background(theme.ColorBackground)
	parents := base.Foreground(theme.ColorDim).Render("Sessions › " + project + " › ")
	active := base.Foreground(theme.ColorSecondary).Bold(true).Render(shortID(m.open.ID))
	return theme.PadWithBg(theme.Bg(" ")+parents+active, width)
}

// status is derived on every frame, with no timer (Rule 128).
//
// The empty sentence needs the listing to be empty in total, not after the
// filter: a filter with no match is not a machine with no sessions.
func (m Model) status() sharedcomponents.Status {
	if m.level == levelAgents {
		return m.agentsStatus()
	}
	switch {
	case m.loadErr:
		return sharedcomponents.Status{
			Text:  "Failed to list Claude Code sessions — check logs",
			Level: sharedcomponents.LevelError,
		}
	case m.loading:
		return sharedcomponents.Status{Text: "Reading Claude Code sessions...", Spinner: true}
	case len(m.table.Items()) == 0:
		return sharedcomponents.Status{Text: "No Claude Code sessions found in " + theme.FoldHome(m.root)}
	}
	return sharedcomponents.Status{}
}

// agentsStatus is the footer state of the agents level.
func (m Model) agentsStatus() sharedcomponents.Status {
	switch {
	case m.agentsErr:
		return sharedcomponents.Status{
			Text:  "Failed to read this session — check logs",
			Level: sharedcomponents.LevelError,
		}
	case m.agentsLoading:
		return sharedcomponents.Status{Text: "Reading session...", Spinner: true}
	case m.usage.Diagnostics.Degraded():
		return sharedcomponents.Status{
			Text:  "Totals are approximate — some transcript data could not be read",
			Level: sharedcomponents.LevelWarning,
		}
	}
	return sharedcomponents.Status{}
}

// Package agentusageview is the `:agent-usage` screen: the Claude Code
// sessions found on this machine.
//
// It reads transcripts' working directory and date only, never their content
// (internal/agentusage owns that guarantee).
package agentusageview

import (
	"github.com/charmbracelet/bubbles/spinner"
	tea "github.com/charmbracelet/bubbletea"

	"github.com/anthnel/devdesk/internal/agentusage"
	"github.com/anthnel/devdesk/internal/config"
	sharedcomponents "github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/datatable"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// sessionRow is one table row. project is computed once, in Update, so a Cell
// never touches the file system or the environment.
type sessionRow struct {
	agentusage.Session
	project string // theme.FoldHome(Project), or "-" when unknown
}

// sessionListLoadedMsg carries one listing. gen drops an answer to a read that
// a newer one has superseded.
type sessionListLoadedMsg struct {
	gen     int
	root    string
	listing agentusage.Listing
	err     error
}

// sessionUsageLoadedMsg carries one parsed session. gen is agentGen at the time
// the parse started: it drops the answer for a session left or re-read since.
type sessionUsageLoadedMsg struct {
	gen   int
	usage agentusage.Usage
	err   error
}

// level is the screen on view: the sessions, or the agents of one session.
type level int

const (
	levelSessions level = iota
	levelAgents
)

// Model is the agent usage view.
type Model struct {
	table   datatable.Model[sessionRow]
	spinner spinner.Model
	footer  sharedcomponents.FooterMessage

	// level says which table is on screen. The sessions table keeps its cursor
	// and filter while the agents level is open.
	level level
	// agentTable lists the agents of open.
	agentTable datatable.Model[agentRow]
	open       agentusage.Session
	// usage is the last parse of open, kept for what the footer says about it.
	usage agentusage.Usage
	// agentGen numbers the parses, as gen numbers the listings.
	agentGen      int
	agentsLoading bool
	// agentsErr says the most recent parse failed (a state, like loadErr).
	agentsErr bool
	// width and height are the last viewport size, for both tables.
	width, height int

	// gen numbers the reads; only the answer to the latest one is kept.
	gen     int
	loading bool
	// loadErr says the most recent read failed. It is a state rather than a
	// timed message so the empty-listing sentence cannot take its place.
	loadErr bool
	// root is the projects directory the last successful read listed.
	root    string
	omitted int
}

// New builds the view with its first read pending.
func New(_ *config.Config) Model {
	sp := spinner.New()
	sp.Spinner = spinner.Dot
	sp.Style = theme.SpinnerStyle()

	return Model{
		loading: true,
		spinner: sp,
		table: datatable.New(datatable.Config[sessionRow]{
			Columns: sessionColumns(),
			// The listing arrives newest first, which is the order wanted.
			SortColumn: -1,
		}),
		agentTable: datatable.New(datatable.Config[agentRow]{
			Columns: agentColumns(),
			// The order is the tree: orchestrator, then sub-agents.
			SortColumn: -1,
		}),
	}
}

// Init starts the first read and the spinner.
func (m Model) Init() tea.Cmd {
	cmds := []tea.Cmd{listSessionsCmd(m.gen), m.spinner.Tick}
	if m.level == levelAgents {
		cmds = append(cmds, parseSessionCmd(m.agentGen, m.open.Parent))
	}
	return tea.Batch(cmds...)
}

package agentusageview

import (
	tea "github.com/charmbracelet/bubbletea"

	"github.com/anthnel/devdesk/internal/ui/shortcut"
)

// The reasons, written once so the header, the footer and the tests cannot
// drift apart on the wording (Rule 129 — English US).
const (
	reasonNoSession      = "No session to open"
	reasonInsideSession  = "Already inside a session"
	reasonTopLevel       = "Already at the session list"
	reasonAgentsUnsorted = "Agents are listed as a tree — nothing to sort"
)

// actions is what the keys allow right now, computed once and read by both
// halves of the view: GetShortcuts to grey out, the handlers to refuse
// (Rule 130).
type actions struct {
	Open  shortcut.Availability // → and enter
	Close shortcut.Availability // ← and esc
	Sort  shortcut.Availability // .
}

// availability computes the three answers from the level and the selected row.
func (m Model) availability() actions {
	var a actions
	if m.level == levelAgents {
		a.Open = shortcut.Unavailable(reasonInsideSession)
		a.Sort = shortcut.Unavailable(reasonAgentsUnsorted)
		return a
	}
	a.Close = shortcut.Unavailable(reasonTopLevel)
	if _, ok := m.table.Selected(); !ok {
		a.Open = shortcut.Unavailable(reasonNoSession)
	}
	return a
}

// guard runs act when the action is available, and otherwise refuses with the
// reason as a Warn: nothing failed, the action does not apply (Rule 128).
func (m Model) guard(a shortcut.Availability, act func() (tea.Model, tea.Cmd)) (tea.Model, tea.Cmd) {
	if !a.Enabled() {
		return m, m.footer.Warn(a.Reason)
	}
	return act()
}

package agentusageview

import "github.com/anthnel/devdesk/internal/ui/help"

// GetHelpContent returns the help for `?` (Rule 114).
func (m Model) GetHelpContent() help.Content {
	return help.Content{
		Title: "Agent usage",
		Description: "The Claude Code sessions found on this machine, newest first. " +
			"Only where and when a session ran is read — nothing a session says.",
		KeyBindings: []help.KeyBinding{
			{Key: "ctrl+r", Description: "Read the sessions, or the open session, again"},
			{Key: "→/enter", Description: "Open the selected session's agents"},
			{Key: "←/esc", Description: "Back to the sessions"},
			{Key: "/", Description: "Filter by project or session ID"},
			{Key: ".", Description: "Cycle the sort column (sessions only)"},
			{Key: "ctrl+p", Description: "Open command mode"},
			{Key: "?", Description: "Show this help"},
		},
		Sections: []help.Section{
			{
				Title: "Columns",
				Body: "Project: the working directory the session ran in, with your home folded to ~. " +
					"A long path is cut from the left so the project's own name stays visible; a dash means the transcript named none.\n" +
					"Last active: when the session's transcript was last written, in local time.\n" +
					"Session: the start of the session ID. The filter matches the full ID.",
			},
			{
				Title: "Where sessions come from",
				Body: "Claude Code keeps one transcript per session under projects/ in its configuration directory: " +
					"$CLAUDE_CONFIG_DIR when set, otherwise ~/.claude. " +
					"Claude Code deletes old transcripts itself (after 30 days by default), so older sessions disappear from here too.\n" +
					"Sessions that could not be listed (symbolic links, which are refused rather than followed, unreadable directories, " +
					"or sessions beyond the listing cap) are counted as Skipped in the header.",
			},
			{
				Title: "Agents",
				Body: "Opening a session lists its agents: the orchestrator first, then each sub-agent with its type, " +
					"as a tree, with the models used and the tokens in, out, and cached.\n" +
					"A ≥ before an Out count means a floor: that sub-agent's transcript was still being written, so the real figure is higher.\n" +
					"The orchestrator is the main conversation; its figures are never a floor.\n" +
					"When part of a transcript could not be read, the footer says the totals are approximate.",
			},
			{
				Title: "Privacy",
				Body: "The sessions list reads the working directory and the file date alone. " +
					"Opening a session also reads its token counts, model names and agent types, and shows only the project's working directory, the date, the session ID, the agent types, the models and the tokens. " +
					"Prompts, replies, tool output and the paths of files a session touched are never displayed and never logged.",
			},
		},
	}
}

package agentusage

// Agent is the usage of one agent of a session: the orchestrator (Main) or a
// sub-agent.
type Agent struct {
	ID              string
	Main            bool
	Type            string // sub-agent type from its meta file; "" if unknown
	Models          []string
	Tokens          Tokens
	Messages        int // distinct message ids
	PartialMessages int // messages whose last line has no stop reason
	State           State
	SpawnDepth      int
}

// PartialOutput reports whether some message of the agent was still being
// written (no stop reason on its last line), so its output count is a floor.
func (a Agent) PartialOutput() bool { return a.PartialMessages > 0 }

// IssueKind classifies a line that could not be counted.
type IssueKind int

const (
	IssueUnreadable IssueKind = iota // not JSON, truncated, or bad counters
	IssueOversized                   // longer than MaxLineBytes
	IssueOpenFailed                  // a sub-agent transcript could not be opened
	IssueReadError                   // reading stopped on an I/O error at Offset
)

// FileIssue locates one skipped line. File is a base name, never a path.
type FileIssue struct {
	File   string
	Offset int64
	Kind   IssueKind
}

// Diagnostics counts what parsing skipped or had to guess.
type Diagnostics struct {
	UnreadableLines     int
	OversizedLines      int
	NoUsage             int
	NoMessageID         int
	CrossFileDuplicates int
	MetaMissing         int
	MetaUnreadable      int
	TruncatedFiles      []string
	Files               []FileIssue
}

// Degraded reports whether anything was skipped or guessed.
func (d Diagnostics) Degraded() bool {
	return d.UnreadableLines > 0 || d.OversizedLines > 0 || d.NoUsage > 0 ||
		d.NoMessageID > 0 || d.CrossFileDuplicates > 0 || d.MetaMissing > 0 ||
		d.MetaUnreadable > 0 || len(d.TruncatedFiles) > 0 || len(d.Files) > 0
}

// Usage is the parsed usage of one session.
type Usage struct {
	SessionID   string
	Agents      []Agent
	Versions    []string
	Diagnostics Diagnostics
}

// Total returns the tokens of every agent.
func (u Usage) Total() Tokens {
	var t Tokens
	for _, a := range u.Agents {
		t = t.Add(a.Tokens)
	}
	return t
}

