1	package agentusageview
2	
3	import (
4		"fmt"
5		"sort"
6		"strings"
7	
8		"github.com/charmbracelet/lipgloss"
9	
10		"github.com/anthnel/devdesk/internal/agentusage"
11		"github.com/anthnel/devdesk/internal/ui/datatable"
12		"github.com/anthnel/devdesk/internal/ui/theme"
13	)
14	
15	const (
16		// noModel stands for an agent whose transcript named no model.
17		noModel = "-"
18		// unknownType stands for a sub-agent whose meta file gave no type.
19		unknownType = "unknown"
20		// orchestratorLabel is the Agent cell of the main agent.
21		orchestratorLabel = "orchestrator"
22		// partialMark prefixes an output count that is a floor, not an exact value.
23		partialMark = "≥ "
24		// stem and lastStem draw the tree branch in front of a sub-agent's type.
25		stem     = "├─ "
26		lastStem = "└─ "
27	)
28	
29	// agentRow is one line of the agents table: an agent, and whether it is the
30	// last sub-agent, which decides the shape of its branch.
31	type agentRow struct {
32		agentusage.Agent
33		last bool
34	}
35	
36	// agentRows orders a session's agents: the orchestrator first, then the
37	// sub-agents by ID. The sort is stable so equal IDs keep their input order.
38	func agentRows(u agentusage.Usage) []agentRow {
39		var main, subs []agentusage.Agent
40		for _, a := range u.Agents {
41			if a.Main {
42				main = append(main, a)
43			} else {
44				subs = append(subs, a)
45			}
46		}
47		sort.SliceStable(subs, func(i, j int) bool { return subs[i].ID < subs[j].ID })
48	
49		rows := make([]agentRow, 0, len(u.Agents))
50		for _, a := range main {
51			rows = append(rows, agentRow{Agent: a})
52		}
53		for i, a := range subs {
54			rows = append(rows, agentRow{Agent: a, last: i == len(subs)-1})
55		}
56		return rows
57	}
58	
59	// agentColumns describes the agents table. Nothing sorts: the order is the
60	// tree. Cache columns give way first on a narrow terminal, writes before reads.
61	func agentColumns() []datatable.Column[agentRow] {
62		count := func(title string, width int, tokens func(agentRow) int64) datatable.Column[agentRow] {
63			return datatable.Column[agentRow]{
64				Title: title, Sizing: datatable.SizingFixed, MinWidth: width,
65				Cell:  func(r agentRow) string { return formatTokens(tokens(r)) },
66				Style: func(r agentRow) lipgloss.Style { return dimWhen(tokens(r) == 0) },
67			}
68		}
69		in := count("In", 6, func(r agentRow) int64 { return r.Tokens.Input })
70		cacheRead := count("Cache read", len("Cache read"), func(r agentRow) int64 { return r.Tokens.CacheRead })
71		cacheRead.Optional = true
72		cacheWrite := count("Cache write", len("Cache write"), func(r agentRow) int64 { return r.Tokens.CacheWrite })
73		cacheWrite.Optional, cacheWrite.DropFirst = true, true
74		total := count("Total", 6, func(r agentRow) int64 { return r.Tokens.Total() })
75	
76		out := count("Out", 7, nil)
77		out.Cell = outCell
78		out.Style = func(r agentRow) lipgloss.Style { return dimWhen(r.Tokens.Output == 0) }
79	
80		return []datatable.Column[agentRow]{
81			{Title: "Agent", Sizing: datatable.SizingContent, MinWidth: 14, Cell: roleCell, Search: agentSearch,
82				Style: func(r agentRow) lipgloss.Style { return dimWhen(!r.Main && r.Type == "") }},
83			{Title: "Model", Sizing: datatable.SizingContent, MinWidth: 12, Flex: 2, Cell: modelsCell, Search: modelsCell,
84				Style: func(r agentRow) lipgloss.Style { return dimWhen(len(r.Models) == 0) }},
85			in, out, cacheRead, cacheWrite, total,
86		}
87	}
88	
89	// dimWhen is Rule 122's colour discipline: a zero or a placeholder is dim,
90	// anything else keeps the default colour.
91	func dimWhen(dim bool) lipgloss.Style {
92		if dim {
93			return theme.DimStyle
94		}
95		return lipgloss.NewStyle()
96	}
97	
98	// agentSearch is what `/` matches in the Agent column: the role and the ID,
99	// which no column shows.
100	func agentSearch(r agentRow) string { return roleCell(r) + " " + r.ID }
101	
102	// roleCell is the Agent cell: "orchestrator", or the sub-agent's type behind
103	// its branch.
104	func roleCell(r agentRow) string {
105		if r.Main {
106			return orchestratorLabel
107		}
108		typ := r.Type
109		if typ == "" {
110			typ = unknownType
111		}
112		if r.last {
113			return lastStem + typ
114		}
115		return stem + typ
116	}
117	
118	// modelsCell lists the models the agent used.
119	func modelsCell(r agentRow) string {
120		if len(r.Models) == 0 {
121			return noModel
122		}
123		return strings.Join(r.Models, ", ")
124	}
125	
126	// outCell is the output count. A sub-agent still being written is a floor and
127	// says so; the orchestrator never does, its transcript is the one being read.
128	func outCell(r agentRow) string {
129		out := formatTokens(r.Tokens.Output)
130		if !r.Main && r.PartialOutput() {
131			return partialMark + out
132		}
133		return out
134	}
135	
136	// formatTokens renders a count compactly, floored to one decimal: 1099 is
137	// "1.0k", never "1.1k". From 100 of a unit up the decimal is dropped.
138	func formatTokens(n int64) string {
139		units := []struct {
140			size   int64
141			suffix string
142		}{
143			{1_000_000_000_000, "T"}, {1_000_000_000, "B"}, {1_000_000, "M"}, {1_000, "k"},
144		}
145		for _, u := range units {
146			if n < u.size {
147				continue
148			}
149			tenths := n / (u.size / 10) // divide first: n*10 would overflow
150			if tenths >= 1000 {
151				return fmt.Sprintf("%d%s", tenths/10, u.suffix)
152			}
153			return fmt.Sprintf("%d.%d%s", tenths/10, tenths%10, u.suffix)
154		}
155		return fmt.Sprintf("%d", n)
156	}
157

