14	// Update handles messages.
15	func (m Model) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
16		switch msg := msg.(type) {
17		case tea.WindowSizeMsg:
18			return m.handleResize(msg)
19		case sessionListLoadedMsg:
20			return m.handleListLoaded(msg)
21		case sessionUsageLoadedMsg:
22			return m.handleUsageLoaded(msg)
23		case spinner.TickMsg:
24			return m.handleSpinnerTick(msg)
25		case tea.KeyMsg:
26			return m.handleKey(msg)
27		}
28		m.footer.Handle(msg)
29		return m, nil
30	}
