32	// handleResize sizes both tables, so going back from the agents level finds the
33	// sessions table already fitted. The full viewport width, borders included
34	// (Rule 116).
35	func (m Model) handleResize(msg tea.WindowSizeMsg) (tea.Model, tea.Cmd) {
36		m.width, m.height = msg.Width, max(msg.Height-1, 1)
37		m.table.Resize(m.width, m.height)
38		m.agentTable.Resize(m.width, m.height)
39		return m, nil
40	}
41	
42	// handleListLoaded takes a listing, or ignores one from a superseded read.
43	// A failed read keeps the rows already shown: they are dated, not wrong.
44	func (m Model) handleListLoaded(msg sessionListLoadedMsg) (tea.Model, tea.Cmd) {
45		if msg.gen != m.gen {
46			return m, nil
47		}
48		m.loading = false
49		if msg.err != nil {
50			// The error can name a path; it is logged, never shown (Rule 128).
51			log.Printf("ERROR [agentusageview] list sessions: %v", msg.err)
52			m.loadErr = true
53			return m, nil
54		}
55		m.loadErr = false
56		m.root = msg.root
57		m.omitted = msg.listing.Omitted
58		m.table.SetItems(rowsOf(msg))
59		return m, nil
60	}
61	
62	// rowsOf folds each project once, so no Cell does it per frame.
63	func rowsOf(msg sessionListLoadedMsg) []sessionRow {
64		rows := make([]sessionRow, len(msg.listing.Sessions))
65		for i, s := range msg.listing.Sessions {
66			project := noProject
67			if s.Project != "" {
68				project = theme.FoldHome(s.Project)
69			}
70			rows[i] = sessionRow{Session: s, project: project}
71		}
72		return rows
73	}
74	
75	// handleSpinnerTick advances the spinner only while a read or a parse is in
76	// flight, so the chain ends with the load.
77	func (m Model) handleSpinnerTick(msg spinner.TickMsg) (tea.Model, tea.Cmd) {
78		if !m.loading && !m.agentsLoading {
79			return m, nil
80		}
81		var cmd tea.Cmd
82		m.spinner, cmd = m.spinner.Update(msg)
83		m.footer.SetSpinnerFrame(m.spinner.View())
84		return m, cmd
85	}
86	
87	// handleUsageLoaded takes a parsed session, or ignores one for a session that
88	// was left or re-read since. A failed refresh keeps the rows already shown.
89	func (m Model) handleUsageLoaded(msg sessionUsageLoadedMsg) (tea.Model, tea.Cmd) {
90		if msg.gen != m.agentGen || m.level != levelAgents {
91			return m, nil
92		}
93		m.agentsLoading = false
94		if msg.err != nil {
95			// The error names the file by base name only; the path stays out.
96			log.Printf("ERROR [agentusageview] read session: %v", msg.err)
97			m.agentsErr = true
98			return m, nil
99		}
100		m.agentsErr = false
101		m.usage = msg.usage
102		m.agentTable.SetItems(agentRows(msg.usage))
103		m.agentTable.Remeasure() // another session is another population
104		return m, nil
105	}
106	
107	// handleKey gives the filter the keyboard first; ctrl+r refreshes the level on
108	// screen, → and enter open a session, ← and esc go back.
109	func (m Model) handleKey(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
110		if m.InEditMode() {
111			return m, m.activeTable(msg)
112		}
113		key := msg.String()
114		if key == "ctrl+r" {
115			return m.refresh()
116		}
117		a := m.availability()
118		switch key {
119		case "right", "enter":
120			return m.guard(a.Open, m.openSelected)
121		case "left", "esc":
122			// Silent at the top level: a stray esc is not worth a footer line.
123			if a.Close.Enabled() {
124				return m.closeAgents()
125			}
126		case ".":
127			if !a.Sort.Enabled() {
128				return m, m.footer.Warn(a.Sort.Reason)
129			}
130		}
131		return m, m.activeTable(msg)
132	}
133	
134	// activeTable hands a key to the table of the level on screen.
135	func (m *Model) activeTable(msg tea.KeyMsg) tea.Cmd {
136		if m.level == levelAgents {
137			return m.agentTable.Update(msg)
138		}
139		return m.table.Update(msg)
140	}
141	
142	// openSelected opens the selected session's agents. The table stays empty,
143	// headers included, until the parse answers (Rule 139).
144	func (m Model) openSelected() (tea.Model, tea.Cmd) {
145		row, _ := m.table.Selected() // availability checked a row exists
146		m.usage = agentusage.Usage{}
147		m.level = levelAgents
148		m.open = row.Session
149		m.agentGen++
150		m.agentsLoading, m.agentsErr = true, false
151		m.agentTable.FilterBar().ClearSearch() // a filter typed for another session
152		m.agentTable.SetItems(nil)
153		return m, tea.Batch(parseSessionCmd(m.agentGen, m.open.Parent), m.spinner.Tick)
154	}
155	
156	// closeAgents returns to the sessions, cursor and filter as they were. Bumping
157	// agentGen drops a parse still in flight.
158	func (m Model) closeAgents() (tea.Model, tea.Cmd) {
159		m.level = levelSessions
160		m.agentGen++
161		m.agentsLoading, m.agentsErr = false, false
162		m.usage = agentusage.Usage{}
163		m.agentTable.SetItems(nil)
164		return m, nil
165	}
166	
167	// refresh starts a new read of the level on screen under a new generation.
168	// The rows stay on screen.
169	func (m Model) refresh() (tea.Model, tea.Cmd) {
170		if m.level == levelAgents {
171			m.agentGen++
172			m.agentsLoading = true
173			return m, tea.Batch(parseSessionCmd(m.agentGen, m.open.Parent), m.spinner.Tick)
174		}
175		m.gen++
176		m.loading = true
177		m.loadErr = false
178		return m, tea.Batch(listSessionsCmd(m.gen), m.spinner.Tick)
179	}
