		if col.Title != wantTitles[i] {
			t.Errorf("column %d = %q, want %q", i, col.Title, wantTitles[i])
		}
		if col.Sizing == datatable.SizingUnset {
			t.Errorf("column %q has no Sizing", col.Title)
